package com.rescuefarm.ui.seller;import android.content.Context;import androidx.annotation.NonNull;import androidx.lifecycle.*;import com.google.firebase.auth.FirebaseAuth;import com.rescuefarm.data.repository.*;public class SellerViewModelFactory implements ViewModelProvider.Factory{private final Context c;public SellerViewModelFactory(Context x){c=x.getApplicationContext();}@NonNull public <T extends ViewModel>T create(@NonNull Class<T>x){String uid=FirebaseAuth.getInstance().getCurrentUser()==null?"":FirebaseAuth.getInstance().getCurrentUser().getUid();return (T)new SellerViewModel(uid);}}
